  {"clause_id": "c020", "issues": []},
  {"clause_id": "c021", "issues": [
    {"issue": "Termination is available if Recipient \"breaches any term,\" with no materiality threshold, and the agreement fixes no term or expiration date at all. Whether any breach however trivial triggers the right, and how long the MTA otherwise runs, are both left open.", "type": 1, "prob": 0.18}
