  ]},
  {"clause_id": "c025", "issues": []},
  {"clause_id": "c026", "issues": []},
  {"clause_id": "c027", "issues": [
    {"issue": "The letter requires return of a copy \"signed by you and by an authorized official of your institution,\" leaving open whether both signatures are a condition of formation and what the effect is if one is missing or undated. The execution block, which provides separate lines for the Recipient Scientist and the Institution Official, makes that question live.", "type": 1, "prob": 0.32}
  ]},
  {"clause_id": "c028", "issues": [
    {"issue": "\"The Materials will be forwarded to you upon receipt of the signed letter\" makes delivery turn on the signature required by the preceding execution paragraph, so if the Materials were shipped before or without a fully executed copy it is unclear whether the terms attach at all. Whether this sentence states a condition precedent or merely describes logistics is the question.", "type": 2, "prob": 0.22}
  ]}
]}

